(function(){
  var P = AutoJS.players()[0];
  AutoJS.command('kill @e[type=!player,distance=..48]');
  AutoJS.command('clear @a');
  AutoJS.command('effect clear @a');
  function count(id){
    var inv = P.getInventory(); var n = 0;
    for (var i = 0; i < inv.getContainerSize(); i++){
      var s = inv.getItem(i);
      if (!s.isEmpty() && String(AutoJS.id(s)) === id) n += s.getCount();
    }
    return n;
  }
  AutoJS.give('minecraft:gold_ingot', 2);
  AutoJS.give('astral_dice:star_plate', 1);
  AutoJS.give('minecraft:polished_blackstone_bricks', 5);
  AutoJS.give('astral_dice:blank_chip', 1);
  var out = {};
  out.goldBefore = count('minecraft:gold_ingot');
  out.plateBefore = count('astral_dice:star_plate');
  out.bricksBefore = count('minecraft:polished_blackstone_bricks');
  out.blankChipBefore = count('astral_dice:blank_chip');
  var list = JSON.parse(AutoJS.craftable(400));
  var found = null;
  for (var i = 0; i < list.length; i++){ if (String(list[i].recipe) === 'astral_dice:chip_shop') found = list[i]; }
  out.recipeListed = (found !== null);
  out.listedOutput = (found === null) ? '' : String(found.output);
  var res = JSON.parse(AutoJS.craft('astral_dice:chip_shop', 1));
  out.craftRecipe = String(res.recipe);
  out.crafted = res.crafted;
  out.craftOutput = String(res.output);
  out.goldAfter = count('minecraft:gold_ingot');
  out.plateAfter = count('astral_dice:star_plate');
  out.bricksAfter = count('minecraft:polished_blackstone_bricks');
  out.blankChipAfter = count('astral_dice:blank_chip');
  out.chipShopAfter = count('astral_dice:chip_shop');
  var list2 = JSON.parse(AutoJS.craftable(400));
  var still = false;
  for (var j = 0; j < list2.length; j++){ if (String(list2[j].recipe) === 'astral_dice:chip_shop') still = true; }
  out.stillCraftableAfter = still;
  return out;
})()

(function(){
  AutoJS.command('clear @a');
  AutoJS.command('effect clear @a');
  AutoJS.command('kill @e[type=!player,distance=..48]');
  return { cleaned: true };
})()
